// Publish exported organic checkpoints as source assets for every installation.
// Usage: npm run bundle:brains -- path/to/ai-racer-captured-milestones.json
import fs from 'node:fs';
import { CONFIG } from '../js/config.js';
import { Track, TRACK_PRESETS } from '../js/track.js';
import { compatibleCaptures } from '../js/milestones.js';
import { PRESET_BRAINS } from '../js/presetBrains.js';

const file = process.argv[2];
if (!file) throw new Error('Provide the Export captured brains JSON file.');
const input = JSON.parse(fs.readFileSync(file, 'utf8'));
// Both the milestone picker and the general brain export carry checkpoint data.
input.presets = input.presets ?? input.capturedPresets;
const presetTrack = TRACK_PRESETS[input.track];
if (input.version !== 1 || !presetTrack || !Array.isArray(input.presets) || !input.presets.length) throw new Error('Expected a nonempty captured milestone export with a known track.');
const track = new Track(presetTrack.points, CONFIG.track.width, CONFIG.track.samples);
const valid = compatibleCaptures(input.presets, track, CONFIG);
if (valid.length !== input.presets.length) throw new Error('Export contains invalid or incompatible captures; bundle was not changed.');
if (new Set(valid.map(p => p.gen)).size !== valid.length) throw new Error('Duplicate milestone generations in export; bundle was not changed.');
const merged = { ...PRESET_BRAINS };
for (const preset of valid) merged[`${input.track}:${preset.gen}`] = preset;
// Share repeated signatures in source while retaining each capture's exact data.
const signatures = [...new Set(Object.values(merged).map(p => p.physicsSignature))];
const entries = Object.entries(merged).sort(([a], [b]) => a.localeCompare(b, 'en', { numeric: true })).map(([key, preset]) => {
  const { physicsSignature, ...rest } = preset;
  return `  ${JSON.stringify(key)}: { ...${JSON.stringify(rest)}, physicsSignature: signatures[${signatures.indexOf(physicsSignature)}] }`;
});
const source = '// Bundled, organically tested milestone brains. Generated by npm run bundle:brains.\n' +
  "export { PRESET_MILESTONES } from './milestones.js';\n" +
  `const signatures = ${JSON.stringify(signatures)};\nexport const PRESET_BRAINS = {\n${entries.join(',\n')}\n};\n`;
fs.writeFileSync(new URL('../js/presetBrains.js', import.meta.url), source);
console.log(`Bundled ${valid.length} tested ${input.track} milestones. Total available: ${Object.keys(merged).length}.`);
